SELECT game_id AS "gameId", entity_id AS "entityId", attr_key AS "attrKey", stage AS stage, value AS value, change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.entity_attribute_stage_values WHERE game_id = #{gameId}
AND entity_id = #{entityId}
AND attr_key = #{attrKey}
ORDER BY entity_id, attr_key, stage

 SELECT
game_id AS "gameId",
entity_id AS "entityId",
attr_key AS "attrKey",
stage AS stage,
value AS value,
change_revision AS "changeRevision",
updated_at AS "updatedAt"
 FROM public.entity_attribute_stage_values
 WHERE game_id = #{gameId}
   AND entity_id = #{entityId}
   AND attr_key = #{attrKey}
   AND stage = #{stage}
